-- Employees. First and last name are separate fields.
CREATE TABLE "OHEM" (
    "empID"     INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "firstName" VARCHAR(50) NOT NULL,
    "lastName"  VARCHAR(50) NOT NULL,
    "jobTitle"  VARCHAR(20),
    "Active"    VARCHAR(1)  NOT NULL DEFAULT 'Y' CHECK ("Active" IN ('Y', 'N'))
);
